"""Accessible public sample UI for Townlight Budget."""

def render_public_lookup_page() -> str:
    return """<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<link rel="icon" href="data:,"><title>Townlight Budget - budget narrative support</title><style>:root{--ink:#17202a;--blue:#24507a;--pale:#e8f1fb;--gold:#bf8f35;--paper:#fffaf0}body{margin:0;font-family:'Aptos','Segoe UI',sans-serif;color:var(--ink);background:linear-gradient(135deg,#eef6ff,var(--paper))}header,main,footer{width:min(1080px,calc(100% - 32px));margin:auto}header{padding:52px 0 20px}.eyebrow{text-transform:uppercase;letter-spacing:.14em;color:var(--blue);font-weight:900}h1{font:800 clamp(2.35rem,7vw,5.2rem)/.95 Georgia,serif;margin:.1em 0}.lede{font-size:1.2rem;line-height:1.6;max-width:850px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:rgba(255,255,255,.92);border:1px solid #bad0e8;border-radius:24px;padding:24px;box-shadow:0 18px 36px #26313b18}.badge{display:inline-block;background:var(--blue);color:white;padding:.5rem .85rem;border-radius:999px;font-weight:900}code{background:var(--pale);padding:.1rem .35rem;border-radius:.35rem}:focus-visible{outline:4px solid var(--gold);outline-offset:3px}@media(max-width:720px){.grid{grid-template-columns:1fr}header{padding-top:34px}}</style></head><body><header><p class="eyebrow">Townlight / Townlight Budget</p><h1>Budget narratives without replacing the ERP.</h1><p class="lede">Townlight Budget v0.2.0 is a Windows source candidate. It helps staff draft department narratives, line-item variance notes, hearing packet checklists, resident summaries, optional GFOA alignment checklists, and protected persisted retrieval. Windows suite integration supports saved finance review, council adoption, and reviewed resident publication; accounting, payroll, and ERP remain external.</p><p><span class="badge">v0.2.0 Windows source candidate</span></p></header><main><section class="grid"><article class="card"><h2>Available Today</h2><ul><li>Line-item variance review.</li><li>Budget narrative and memo drafts.</li><li>Hearing packet checklists.</li><li>Resident plain-English summaries.</li><li>GFOA alignment checklist.</li><li>Standalone public page serves workpapers at the existing path.</li></ul></article><article class="card"><h2>Human approval required</h2><p>Finance staff approve all budget numbers, narratives, hearing packets, and public summaries.</p></article><article class="card"><h2>Boundaries</h2><p>Windows suite integration supports saved finance review, council adoption, and reviewed resident publication; accounting, payroll, fund accounting, and ERP remain external, and live LLM calls and live finance-system connectors remain unavailable.</p></article><article class="card"><h2>Dependency</h2><p>Pinned to source candidate <code>townlight-core==1.3.0.dev2</code>.</p></article><article class="card"><h2>Persisted retrieval protection</h2><p>Stored narrative and hearing packet GET routes require a bearer token mapped in <code>CIVICBUDGET_AUTH_TOKEN_ROLES</code>.</p></article></section></main><footer><p>AGPL-3.0 code. CC BY 4.0 docs.</p></footer></body></html>"""
